SELECT SUM(award_yuan) AS total_award_amount
FROM awards
WHERE award_yuan > 0;

SELECT AVG(award_yuan) AS average_award_amount
FROM awards
WHERE award_yuan > 0;

SELECT COUNT(*) AS announcement_count
FROM announcements
WHERE publish_date >= '2026-10-16' AND publish_date < '2026-10-17';

SELECT COUNT(*) AS count_question
FROM announcements
WHERE publish_date >= '2026-10-15' AND publish_date < '2026-10-16';
